pimp=flow('导入配置包',f'<div style="display:flex;align-items:center;gap:12px;margin-bottom:12px">{B("选择文件","ul")}<span class="t-note">未选择任何文件</span></div>'+fld('配置包内容',TA('{"tscfg_version":"…',96)),B('取消','','lg')+B('仅验证','','lg')+B('导入','','lg primary'),w=560)
pexp=flow('导出配置包',f'<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px">{IN("/sdcard","当前目录","mono","flex:1")}{B("上级目录","","sm")}{IB("refresh","刷新")}</div><div class="card" style="padding:0;background:var(--fill)">'+TR('24px 1fr',['<span class="chk on"></span>','led/effects.json'])+TR('24px 1fr',['<span class="chk"></span>','led/text.json'])+f'</div><div style="display:flex;gap:8px;margin:10px 0">{B("全选","","sm")}{B("取消全选","","sm")}{B("选择整个目录","","sm")}</div>'+ROW(fld('名称',IN('','自动从文件名获取')),fld('描述',IN('','LED 特效配置')))+'<div style="height:12px"></div>'+fld('接收方设备证书',TA('-----BEGIN CERTIFICATE-----',72))+'<div style="height:12px"></div>'+fld('配置包 (.tscfg)',TA('配置包将在此显示...',72)),B('复制到剪贴板','cpy','lg')+B('下载到本地','dl','lg')+B('取消','','lg')+B('生成配置包','','lg primary'),w=760,close=False)
plist=flow('配置包列表',f'<div style="display:flex;gap:8px;margin-bottom:12px">{IN("/sdcard/packs","路径","mono","flex:1")}{IB("refresh","刷新")}</div><div class="card" style="padding:0;background:var(--fill)"><div class="tr" style="--cols:1fr;color:var(--ink-3)">暂无配置包</div></div>',B('关闭','','lg primary'),w=560)
rev=flow('撤销公钥',ROW(fld('主机',IN('','192.168.55.100 或 hostname')),fld('用户名',IN('root','用户名')),fld('端口',IN('22','端口')),cols='1.6fr 1fr 80px')+'<div style="height:12px"></div>'+fld('SSH 登录密码',IN('','输入 SSH 登录密码','','width:100%')),B('取消','','lg')+B('撤销公钥','','lg primary','style="background:var(--bad);border-color:var(--bad)"'),w=620)
mis=flow('主机指纹不匹配',f'<div style="display:flex;gap:8px;align-items:flex-start;color:var(--warn)">{IC["warn"]}<span class="t-body" style="color:var(--ink)">该主机的指纹与已记录的不一致。可能是服务器重装，也可能存在中间人攻击。</span></div><div style="height:12px"></div>'+fld('主机',IN('192.0.2.30','主机','mono'))+'<div style="height:12px"></div>'+fld('已记录指纹',IN('SHA256:aB…','指纹','mono'))+'<div style="height:12px"></div>'+fld('当前指纹',IN('SHA256:xY…','指纹','mono')),B('取消','','lg')+B('更新主机密钥','','lg primary','style="background:var(--bad);border-color:var(--bad)"'),w=560)
imph=flow('导入主机',f'<div class="t-note">Pattern B 表单：主机地址、端口、用户名、部署密钥（字段以现有页面为准，此处仅表示样式）。</div>',B('取消','','lg')+B('导入','','lg primary'),w=460)
