# ---------- 状态与菜单
lang=f'<div class="m-float" style="border-radius:16px;padding:6px;width:180px"><div style="height:32px;border-radius:10px;padding:0 10px;display:flex;align-items:center;gap:8px;">✓ 中文</div><div style="height:32px;border-radius:10px;padding:0 10px;display:flex;align-items:center;gap:8px;padding-left:28px;background:var(--accent-text);color:#fff">English <span style="margin-left:auto;font-size:12px;opacity:.8">悬停</span></div></div>'
toast=lambda k,t:f'<div class="m-float" style="border-radius:16px;padding:12px 16px;display:flex;align-items:center;gap:10px;width:max-content;margin-bottom:10px"><span class="dot {k}"></span><span class="t-body">{t}</span></div>'
alertx=flow('确认删除 fixture-key？',f'<div class="t-body" style="color:var(--ink-2)">此操作无法撤销。替代原生 confirm() / alert()。</div>',B('取消','','lg')+B('删除','','lg primary','style="background:var(--bad);border-color:var(--bad)"'),w=420)
demo=f'''<div class="card" style="background:rgba(255,255,255,.72);padding:0;overflow:hidden">{TR('1fr 120px',['默认行','值'])}<div class="tr hov" style="--cols:1fr 120px"><div>悬停行</div><div>值</div></div><div class="tr rsel" style="--cols:1fr 120px"><div>选中行</div><div>值</div></div></div>
<div style="display:flex;gap:10px;margin-top:14px;align-items:center"><button class="btn">默认</button><button class="btn" style="background:var(--fill-2)">按下</button><button class="btn" style="box-shadow:0 0 0 3px rgba(0,122,255,.38)">焦点</button><button class="btn" disabled style="opacity:.4">禁用</button><span style="display:inline-block;width:16px;height:16px;border-radius:50%;border:2px solid var(--fill-2);border-top-color:var(--accent-text)"></span><span class="t-note">加载中</span></div>'''
stw=f'''<div class="sheet m-float" style="position:relative;width:660px;padding:24px;margin-bottom:40px"><div class="st" style="font-size:20px;margin-bottom:14px">菜单 · 提示 · 状态</div><div class="t-note" style="margin-bottom:8px">语言菜单（模式 D）</div>{lang}<div class="t-note" style="margin:18px 0 8px">Toast（成功 / 信息 / 警告 / 错误）</div>{toast("ok","已保存关机设置")}{toast("","正在连接…")}{toast("warn","输入电压过低：11.8 V")}{toast("bad","保存失败：设备无响应")}<div class="t-note" style="margin:18px 0 8px">列表与控件状态</div>{demo}</div>'''
board('SheetsStates','菜单、提示与状态 目标稿',two(stw,alertx+f'<div class="sheet m-float" style="position:relative;width:660px;padding:24px"><div class="st" style="font-size:20px;margin-bottom:10px">原生对话框清单</div><div class="t-body" style="color:var(--ink-2);line-height:22px">现有 app.js 里有 1 处 <span class="mono">prompt()</span>（WiFi 密码）、1 处 <span class="mono">confirm()</span>（指纹确认）、15 处 <span class="mono">alert()</span>。它们会打断页面、样式无法控制，落地时全部换成上面的模式 A / B 弹窗。</div></div>'))

# ---------- canvas
c=json.load(open(P+'canvas.json'))
extra=[('SheetsAuto','自动化弹窗 目标稿',(0,6560)),('SheetsLed','LED · 网络 · 日志 · 登录 弹窗 目标稿',(1520,6560)),('SheetsSec','安全页弹窗 目标稿',(3040,6560)),('SheetsStates','菜单、提示与状态 目标稿',(0,10100))]
for k,t,(x,y) in extra:
    c['boards'][k+'.dc.html']={'x':x,'y':y,'w':1440,'h':BOARDS[k],'title':t}
    if k+'.dc.html' not in c['order']: c['order'].append(k+'.dc.html')
json.dump(c,open(P+'canvas.json','w'),ensure_ascii=False,indent=1)
